const float HOR = 0.25;
const float YW = -0.22;
const vec2 FB = vec2(0.0, -0.06);

float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7)))*43758.5453); }

float sdVesica(vec2 p, float r, float d){
  p = abs(p);
  float b = sqrt(r*r - d*d);
  return ((p.y-b)*d > p.x*b) ? length(p-vec2(0.0,b)) : length(p-vec2(-d,0.0)) - r;
}

vec3 petalD(vec2 p, vec2 base, float ang, float L, float W, float bend){
  vec2 q = p - base;
  vec2 dir = vec2(sin(ang), cos(ang));
  vec2 nrm = vec2(cos(ang), -sin(ang));
  float y = dot(q, dir);
  float x = dot(q, nrm);
  float yn = clamp(y/L, 0.0, 1.0);
  x -= bend*L*yn*yn;
  x *= mix(1.35, 0.95, yn);
  float b = L*0.5, w = W*0.5;
  float r = 0.5*(w + b*b/w);
  float dd = 0.5*(b*b/w - w);
  float d = sdVesica(vec2(x, y-b), r, dd);
  return vec3(d, yn, x/w);
}

vec3 petalColor(vec3 pd, float br){
  float yn = pd.y, xn = clamp(pd.z, -1.0, 1.0);
  vec3 c = mix(vec3(1.0,0.92,0.9), vec3(0.92,0.32,0.55), smoothstep(0.2,1.0,yn));
  c = mix(c, vec3(0.95,0.85,0.6), (1.0-smoothstep(0.0,0.18,yn))*0.5);
  float v = 0.5+0.5*cos(xn*22.0);
  c *= 0.92+0.08*v;
  c *= 0.75+0.25*(1.0-xn*xn);
  float e = smoothstep(-0.012, 0.0, pd.x);
  c = mix(c, vec3(0.8,0.22,0.45), e*0.6);
  return c*br;
}

void addLayer(inout vec3 col, inout float a, float d, vec3 pc, float px){
  float sh = smoothstep(0.04, 0.0, d)*0.35;
  col *= 1.0 - sh;
  float m = smoothstep(px, -px, d);
  col = col*(1.0-m) + pc*m;
  a = a*(1.0-m) + m;
}

vec4 flower(vec2 p, float o, float t, float px){
  p.x -= sin(t*0.6)*0.012*(p.y - YW)/0.5;
  vec3 col = vec3(0.0);
  float a = 0.0;
  // stem
  float ds = max(abs(p.x)-0.009, max(p.y-FB.y, YW-0.01-p.y));
  addLayer(col, a, ds, vec3(0.05,0.14,0.06)*(0.8+0.4*smoothstep(-0.009,0.009,p.x)), px);
  // sepals
  for(int i=0;i<2;i++){
    float s = float(i)*2.0-1.0;
    vec3 pd = petalD(p, FB, s*(0.5+0.6*o), 0.08, 0.05, 0.0);
    addLayer(col, a, pd.x, vec3(0.08,0.2,0.08), px);
  }
  // back layer
  float sA = mix(0.08, 1.0, o);
  for(int i=0;i<5;i++){
    float f = float(i)-2.0;
    float ang = f*0.67*sA;
    vec2 base = FB + vec2(sin(ang),cos(ang))*0.02*o;
    vec3 pd = petalD(p, base, ang, 0.36, 0.19, -sign(f)*0.12*o);
    addLayer(col, a, pd.x, petalColor(pd, 0.6), px);
  }
  // middle layer
  float sB = mix(0.05, 0.85, o);
  for(int i=0;i<4;i++){
    float f = float(i)-1.5;
    float ang = f*0.66*sB;
    vec2 base = FB + vec2(sin(ang),cos(ang))*0.015*o;
    vec3 pd = petalD(p, base, ang, 0.34, 0.18, -sign(f)*0.1*o);
    addLayer(col, a, pd.x, petalColor(pd, 0.8), px);
  }
  // stamens + pod
  float ps = smoothstep(0.2, 0.8, o);
  if(ps > 0.001){
    vec2 pc = FB + vec2(0.0, 0.1*o);
    vec2 q = p - pc;
    float ds2 = length(q/vec2(0.1,0.05)) - 1.0;
    ds2 *= 0.05/ps;
    float ang = atan(q.y, q.x);
    vec3 stc = vec3(1.0,0.72,0.2)*(0.7+0.3*cos(ang*40.0));
    addLayer(col, a, ds2, stc, px);
    float dp = length(q/vec2(0.065,0.028)) - 1.0;
    dp *= 0.03/ps;
    vec3 podc = mix(vec3(0.75,0.8,0.25), vec3(0.95,0.9,0.45), smoothstep(-0.03,0.03,q.y));
    vec2 sq = q/vec2(0.065,0.028);
    float dots = 0.0;
    for(int k=0;k<7;k++){
      float ka = float(k)*0.8976;
      vec2 dc = (k==0) ? vec2(0.0) : vec2(cos(ka),sin(ka))*0.55;
      dots += smoothstep(0.2, 0.1, length(sq-dc));
    }
    podc = mix(podc, vec3(0.45,0.5,0.15), clamp(dots,0.0,1.0)*0.7);
    addLayer(col, a, dp, podc, px);
  }
  // front layer
  float sC = mix(0.06, 0.95, o);
  for(int i=0;i<3;i++){
    float f = float(i)-1.0;
    float ang = f*1.15*sC;
    float L = (i==1) ? mix(0.33, 0.11, o) : 0.33;
    float W = (i==1) ? mix(0.18, 0.22, o) : 0.18;
    vec2 base = FB + ((i==1) ? vec2(0.0,-0.01) : vec2(sin(ang),cos(ang))*0.01*o);
    vec3 pd = petalD(p, base, ang, L, W, -f*0.12*o);
    addLayer(col, a, pd.x, petalColor(pd, 1.0), px);
  }
  return vec4(col*0.9, a);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord){
  vec2 p = (fragCoord - 0.5*iResolution.xy)/iResolution.y;
  float t = iTime;
  float px = 1.5/iResolution.y;
  float o = smoothstep(0.05, 0.95, 0.5-0.5*cos(t*0.3));
  vec2 moon = vec2(0.55, 0.42);
  vec3 col;

  if(p.y > HOR){
    col = mix(vec3(0.025,0.035,0.08), vec3(0.004,0.006,0.018), smoothstep(HOR, 0.6, p.y));
    vec2 g = floor(p*120.0);
    float h = hash(g);
    vec2 f = fract(p*120.0)-0.5;
    float star = step(0.985, h)*smoothstep(0.3,0.0,length(f))*(0.5+0.5*sin(t*2.0+h*50.0));
    col += vec3(0.8,0.85,1.0)*star*0.6*smoothstep(HOR, HOR+0.1, p.y);
    float md = length(p-moon);
    col += vec3(0.5,0.55,0.7)*0.12*exp(-md*6.0);
    col = mix(col, vec3(0.95,0.93,0.85), smoothstep(0.042, 0.038, md));
    col += vec3(0.06,0.07,0.1)*exp(-(p.y-HOR)*25.0);
  } else {
    float depth = min(1.0/(HOR - p.y), 60.0);
    vec2 P = vec2(p.x*depth, depth);
    vec2 P0 = vec2(0.0, 1.0/(HOR-YW));
    float r = length(P - P0);
    float hgt = sin(r*18.0 - t*2.5)*exp(-r*0.8)*0.6
              + sin(P.x*3.0 + t)*sin(P.y*5.0 - t*1.3)*0.3
              + sin(P.x*7.0 - P.y*4.0 + t*1.7)*0.15;
    vec2 off = vec2(hgt*0.006, hgt*0.012)/depth;
    float fres = pow(smoothstep(-0.5, HOR, p.y), 3.0);
    col = mix(vec3(0.004,0.008,0.018), vec3(0.03,0.045,0.09), fres);
    // moon streak
    float sx = p.x - moon.x + off.x*8.0;
    float streak = exp(-pow(sx*(10.0 + 3.0/depth*0.0),2.0)*(1.0+ (HOR-p.y)*8.0));
    float glit = smoothstep(0.2, 0.9, sin(depth*35.0 + hgt*6.0 + p.x*40.0 + t*2.0));
    col += vec3(0.6,0.62,0.7)*streak*glit*0.35*(0.3+0.7*fres);
    // flower reflection
    vec4 rf = flower(vec2(p.x + off.x, 2.0*YW - p.y + off.y), o, t, px*2.0);
    col = col*(1.0 - rf.a*0.7) + rf.rgb*0.45*vec3(0.85,0.9,1.05);
    vec2 hp = vec2(p.x+off.x, 2.0*YW-p.y+off.y) - FB - vec2(0.0,0.12);
    col += vec3(0.9,0.4,0.6)*0.03*exp(-3.0*length(hp))*(0.4+0.6*o);
    // ripple highlights
    col += vec3(0.15,0.18,0.25)*smoothstep(0.5, 0.9, hgt)*0.15*fres;
    // lily pads
    for(int i=0;i<4;i++){
      vec3 pad = (i==0) ? vec3(-0.9,1.9,0.35) : (i==1) ? vec3(1.1,2.6,0.3) : (i==2) ? vec3(0.35,1.5,0.28) : vec3(-1.6,3.3,0.32);
      vec2 q = P - pad.xy + vec2(sin(t*0.5+float(i)),cos(t*0.4+float(i)*2.0))*0.02;
      float d = length(q) - pad.z;
      float an = atan(q.y, q.x);
      float na = float(i)*1.7 + 0.8;
      float dn = abs(mod(an - na + 3.14159, 6.28318) - 3.14159);
      d = max(d, -(dn - 0.22)*length(q));
      float fw = max(fwidth(d), 1e-4);
      float m = clamp(0.5 - d/fw, 0.0, 1.0);
      float veins = 0.5+0.5*cos(an*14.0);
      vec3 pc = vec3(0.025,0.07,0.035)*(0.8+0.3*veins*smoothstep(0.0,0.1,length(q)));
      pc += vec3(0.05,0.1,0.05)*smoothstep(-0.03, 0.0, d);
      pc *= 0.7 + 0.5*fres;
      col = mix(col*(1.0 - 0.5*smoothstep(0.08,0.0,d)), pc, m);
    }
    col = mix(col, vec3(0.03,0.045,0.08), smoothstep(HOR-0.04, HOR, p.y)*0.6);
  }

  // halo
  col += vec3(0.9,0.4,0.6)*0.06*exp(-3.0*length(p-FB-vec2(0.0,0.12)))*(0.4+0.6*o);

  vec4 fl = flower(p, o, t, px);
  col = col*(1.0 - fl.a) + fl.rgb;

  // fireflies
  for(int i=0;i<6;i++){
    float fi = float(i);
    vec2 fp = vec2(sin(t*0.23 + fi*2.1)*0.7 + 0.1*sin(t*0.7+fi), -0.05 + 0.18*sin(t*0.31 + fi*1.3) + 0.1*fi/6.0);
    float fl2 = 0.5+0.5*sin(t*3.0 + fi*4.0);
    float dd = length(p - fp);
    col += vec3(1.0,0.85,0.4)*(0.00015/(dd*dd + 0.0004))*fl2*0.6;
  }

  vec2 uv = fragCoord/iResolution.xy;
  col *= 0.5 + 0.5*pow(16.0*uv.x*uv.y*(1.0-uv.x)*(1.0-uv.y), 0.25);
  col = pow(max(col, 0.0), vec3(0.4545));
  fragColor = vec4(col, 1.0);
}

