const float YW = -0.08;
const vec2 FB = vec2(0.0, 0.03);

float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7)))*43758.5453); }

float sdVesica(vec2 p, float r, float d){
  p = abs(p);
  float b = sqrt(r*r - d*d);
  return ((p.y-b)*d > p.x*b) ? length(p-vec2(0.0,b)) : length(p-vec2(-d,0.0)) - r;
}

vec3 petalD(vec2 p, vec2 base, float ang, float L, float W, float bend){
  vec2 q = p - base;
  vec2 dir = vec2(sin(ang), cos(ang));
  vec2 nrm = vec2(cos(ang), -sin(ang));
  float y = dot(q, dir);
  float x = dot(q, nrm);
  float yn = clamp(y/L, 0.0, 1.0);
  x -= bend*L*yn*yn;
  x *= mix(1.35, 0.95, yn);
  float b = L*0.5, w = W*0.5;
  float r = 0.5*(w + b*b/w);
  float dd = 0.5*(b*b/w - w);
  float d = sdVesica(vec2(x, y-b), r, dd);
  return vec3(d, yn, x/w);
}

vec3 petalColor(vec3 pd, float br, float hue){
  float yn = pd.y, xn = clamp(pd.z, -1.0, 1.0);
  vec3 tip = mix(vec3(0.92,0.3,0.55), vec3(0.98,0.42,0.6), hue);
  vec3 c = mix(vec3(1.0,0.95,0.92), tip, smoothstep(0.15,1.0,yn));
  c = mix(c, vec3(1.0,0.9,0.55), (1.0-smoothstep(0.0,0.22,yn))*0.6);
  float v = 0.5+0.5*cos(xn*26.0);
  c *= 0.93+0.07*v;
  c *= 0.62+0.38*(1.0-xn*xn);
  c *= 1.0 - 0.18*exp(-xn*xn*120.0)*smoothstep(0.1,0.5,yn);
  float e = smoothstep(-0.014, 0.0, pd.x);
  c = mix(c, vec3(0.7,0.15,0.4), e*0.7);
  return c*br;
}

void addLayer(inout vec3 col, inout float a, float d, vec3 pc, float px){
