vec4 flower(vec2 p, float o, float t, float px){
  p.x -= sin(t*0.6)*0.01*(p.y - YW)/0.4;
  vec3 col = vec3(0.0);
  float a = 0.0;
  float ds = max(abs(p.x)-0.008, max(p.y-FB.y, YW-0.005-p.y));
  addLayer(col, a, ds, vec3(0.05,0.14,0.06)*(0.8+0.4*smoothstep(-0.008,0.008,p.x)), px);
  for(int i=0;i<2;i++){
    float s = float(i)*2.0-1.0;
    vec3 pd = petalD(p, FB, s*(0.45+0.7*o), 0.07, 0.045, 0.0);
    addLayer(col, a, pd.x, vec3(0.08,0.2,0.08), px);
  }
  float sA = mix(0.16, 1.0, o);
  for(int i=0;i<5;i++){
    float f = float(i)-2.0;
    float ang = f*0.67*sA;
    vec2 base = FB + vec2(sin(ang),cos(ang))*0.015*o;
    vec3 pd = petalD(p, base, ang, 0.29, 0.15, -sign(f)*0.12*o);
    addLayer(col, a, pd.x, petalColor(pd, 0.58, fract(float(i)*0.37)), px);
  }
  float sB = mix(0.14, 0.9, o);
  for(int i=0;i<4;i++){
    float f = float(i)-1.5;
    float ang = f*0.62*sB;
    vec2 base = FB + vec2(sin(ang),cos(ang))*0.012*o;
    vec3 pd = petalD(p, base, ang, 0.27, 0.145, -sign(f)*0.1*o);
    addLayer(col, a, pd.x, petalColor(pd, 0.78, fract(float(i)*0.53+0.2)), px);
  }
  float ps = smoothstep(0.35, 0.8, o);
  if(ps > 0.001){
    vec2 pc = FB + vec2(0.0, 0.075*o);
    vec2 q = p - pc;
    float ds2 = length(q/vec2(0.08,0.04)) - 1.0;
    ds2 *= 0.04/ps;
    float ang = atan(q.y, q.x);
    vec3 stc = vec3(1.0,0.75,0.22)*(0.65+0.35*cos(ang*40.0));
    addLayer(col, a, ds2, stc, px);
    vec2 sq = q/vec2(0.052,0.022);
    float dp = (length(sq) - 1.0)*0.022/ps;
    vec3 podc = mix(vec3(0.6,0.72,0.2), vec3(0.92,0.9,0.45), smoothstep(-0.02,0.02,q.y));
    float dots = 0.0;
    for(int k=0;k<7;k++){
      float ka = float(k)*0.8976;
      vec2 dc = (k==0) ? vec2(0.0) : vec2(cos(ka),sin(ka))*0.58;
      dots += smoothstep(0.22, 0.1, length(sq-dc));
    }
    podc = mix(podc, vec3(0.35,0.42,0.1), clamp(dots,0.0,1.0)*0.75);
    addLayer(col, a, dp, podc, px);
  }
  float sC = mix(0.15, 1.0, o);
  for(int i=0;i<3;i++){
    float f = float(i)-1.0;
    float ang = f*1.1*sC;
    float L = (i==1) ? mix(0.26, 0.19, o) : 0.26;
    float W = (i==1) ? mix(0.14, 0.17, o) : 0.14;
    vec2 base = FB + ((i==1) ? vec2(0.0,-0.008) : vec2(sin(ang),cos(ang))*0.008*o);
    vec3 pd = petalD(p, base, ang, L, W, -f*0.12*o);
    addLayer(col, a, pd.x, petalColor(pd, 1.0, fract(float(i)*0.71+0.4)), px);
  }
  return vec4(col*0.9, a);
}

